 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 {h}" role="img" aria-label="{title}"><rect width="1000" height="{h}" rx="20" fill="#f5f8f3"/><style>text{{font-family:"Noto Sans CJK TC",sans-serif;fill:#193c32;font-size:21px}}.sm{{font-size:17px}}.ln{{fill:none;stroke:#28765b;stroke-width:4}}.dash{{stroke-dasharray:8 6}}</style><defs><marker id="arrow" markerWidth="9" markerHeight="9" refX="8" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#28765b"/></marker></defs><text x="35" y="45" font-size="26">{title}</text>{body}</svg>'
