figs.append(('06_雙幹三幹',svg('番茄雙幹與三幹：主幹＋保留強側枝','''<path class="ln" d="M240 350V110M240 260L135 145M650 350V110M650 260L545 145M650 220L755 105"/><text x="155" y="85">雙幹：2 條主軸</text><text x="560" y="85">三幹：3 條主軸</text><text x="260" y="140" class="sm">主幹</text><text x="85" y="190" class="sm">保留側枝</text><text x="670" y="140" class="sm">主幹</text><text x="470" y="205" class="sm">側枝一</text><text x="760" y="175" class="sm">側枝二</text><path stroke="#c34b45" stroke-width="4" d="M240 205L285 180M270 176L280 190M650 300L695 275M680 270L690 285"/><text x="135" y="395" class="sm">通常留第一花序下強側枝；三幹再選另一強枝。其餘側芽及早去除（紅線）。</text><text x="135" y="425" class="sm">實際保留節位隨品種、定植密度及生產目標調整，整枝不可過量去除健康葉。</text>''')))
figs.append(('07_樹體相位',svg('實生果樹相位：同一樹體亦有幼年與成熟部位','''<path class="ln" d="M470 345V160M470 240L280 160M470 220L670 140M470 190L390 100M470 170L550 90"/><ellipse cx="475" cy="140" rx="290" ry="70" fill="#cfe4c9" opacity=".8"/><text x="290" y="145">較晚形成的冠部芽：偏成年相</text><path class="ln" d="M470 320L320 275"/><text x="65" y="285">基部芽、萌蘗：較易保留幼年特徵</text><text x="190" y="385">種子 → 幼年期 → 過渡期 → 成年／結果期 → 衰老</text><text x="115" y="425" class="sm">相位不是單靠高度或年齡判定；修剪、繁殖及返幼可改局部表現，此為概念示意。</text>''')))
