def inline(s):
 s=html.escape(s)
 s=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',lambda m:f'<a href="{m[2]}">{m[1]}</a>',s)
 s=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',s)
 s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
 return s
def md(s):
 out=[]
 for block in re.split(r'\n\s*\n',s.strip()):
  if block.startswith('#'):
   n=len(block)-len(block.lstrip('#'));out.append(f'<h{n}>{inline(block[n:].strip())}</h{n}>')
  elif block.startswith('> '):out.append('<aside>'+inline(block[2:])+'</aside>')
  else:out.append('<p>'+inline(block).replace('\n','<br>')+'</p>')
 return '\n'.join(out)
cards=[];nav=[];books=[];all_years=set()
for file in sorted(ROOT.glob('0[1-7]_*.md')):
 raw=file.read_text();book=file.stem;subject=('園藝植物學' if '園藝植物學' in book else '果樹學' if '果樹學' in book else '花卉學' if '花卉學' in book else '蔬菜學')
 books.append((file.name,book)); year=''; num=0
 for part in re.split(r'(?=^## |^### )',raw,flags=re.M):
  if part.startswith('## '):year=re.search(r'\d+',part).group();all_years.add(year)
  if part.startswith('### '):
   num+=1;heading,_,body=part.partition('\n');title=heading[4:];ident=f'{file.stem[:2]}-{year}-{num}'
   cards.append(f'<details class="question" id="{ident}" data-subject="{subject}" data-year="{year}"><summary><span class="tag">{year} · {subject}</span><span>{html.escape(title)}</span><a class="permalink" href="#{ident}" aria-label="題目永久連結">#</a></summary><div class="answer">{md(body)}</div></details>')
